var e={hostControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Beheer de Linux-host van de printer - controleer de toestand, bestuur de achtergronddiensten, maak schijfruimte vrij en wijzig systeeminstellingen (tijd, locale, hostnaam, netwerk, voeding).`}},view:{monitor:{t:0,b:{t:2,i:[{t:3}],s:`Monitor`}},services:{t:0,b:{t:2,i:[{t:3}],s:`Diensten`}},cleanup:{t:0,b:{t:2,i:[{t:3}],s:`Opschonen`}},system:{t:0,b:{t:2,i:[{t:3}],s:`Systeem`}},boot:{t:0,b:{t:2,i:[{t:3}],s:`Opstarten`}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Help`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Over Host Control`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Sluiten`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Zo lees je dit`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Lees de kaarten voor CPU-temperatuur, geheugen, schijf en netwerk in één oogopslag.`}},{t:0,b:{t:2,i:[{t:3}],s:`Bekijk de tabel met topprocessen om te zien wat de CPU op dit moment gebruikt.`}},{t:0,b:{t:2,i:[{t:3}],s:`Laat automatisch verversen aan voor een live weergave, of zet het uit en ververs handmatig.`}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Hier gebruikte termen`}}},monitor:{title:{t:0,b:{t:2,i:[{t:3}],s:`De monitor lezen`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Alles hier is alleen-lezen. Balken worden oranje boven 75% en rood boven 90%. De CPU-temperatuur wordt oranje bij 70 °C en rood bij 80 °C. De throttling-waarschuwing verschijnt alleen op boards die het melden (vooral Raspberry Pi).`}}},services:{title:{t:0,b:{t:2,i:[{t:3}],s:`Diensten beheren`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Elke rij is een systemd-dienst. Klik er een aan om hem te starten/stoppen/herstarten, in/uit te schakelen bij het opstarten, te maskeren, het logboek te lezen of - voor diensten die je zelf hebt geïnstalleerd - het unit-bestand te verwijderen. Een dienst stoppen of uitschakelen vereist een getypte of one-tap bevestiging. Kritieke en beschermde diensten zijn gemarkeerd; beschermde diensten (zoals SSH en dit paneel) kunnen niet worden gestopt, om te voorkomen dat je jezelf buitensluit.`}}},cleanup:{title:{t:0,b:{t:2,i:[{t:3}],s:`Schijfruimte vrijmaken`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Elke rij wordt eerst gescand om te tonen hoeveel hij zou vrijmaken. Vink aan wat je wilt opruimen en bevestig. Alleen opnieuw te genereren gegevens worden aangeboden - de apt-downloadcache, oud systemd-journaal, ~/.cache, je oude /tmp-bestanden en geroteerde (niet-live) logboeken. Je G-code, timelapses en configs worden nooit aangeraakt.`}}},system:{title:{t:0,b:{t:2,i:[{t:3}],s:`Systeeminstellingen`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Wijzig de tijdzone en klok, taal en toetsenbord, hostnaam of netwerk (DHCP / statisch IP) van de host, of herstart/schakel hem uit. Elke wijziging wordt meteen toegepast. Herstarten en uitschakelen worden geweigerd terwijl er een print loopt. Het wijzigen van het IP kan je verbinding met dit paneel kort verbreken.`}}},network:{title:{t:0,b:{t:2,i:[{t:3}],s:`DHCP versus statisch IP`}},body:{t:0,b:{t:2,i:[{t:3}],s:`DHCP (automatisch) laat je router het adres automatisch toewijzen. Statisch (handmatig) vergrendelt een vast adres - stel het IP, subnet (CIDR, bijv. /24), gateway (meestal je router) en DNS in. Alleen IPv4. Het adres wijzigen van de verbinding die dit paneel bedient verbreekt je sessie; verbind opnieuw op het nieuwe IP. Een verkeerd statisch adres of gateway kan de printer onbereikbaar maken totdat je het op het apparaat zelf herstelt, daarom worden de instellingen gevalideerd en is een getypte bevestiging nodig.`}}}},glossary:{host:{term:{t:0,b:{t:2,i:[{t:3}],s:`Host`}},def:{t:0,b:{t:2,i:[{t:3}],s:`De kleine Linux-computer (bijv. een Raspberry Pi of BTT CB1) die Klipper, Moonraker en FilaMind draait - los van de microcontrollers van de printer.`}}},load:{term:{t:0,b:{t:2,i:[{t:3}],s:`Belastingsgemiddelde`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Hoeveel processen stonden te wachten om te draaien, gemiddeld over 1 / 5 / 15 minuten. Globaal: een waarde rond het aantal cores betekent dat de CPU druk is; ruim daarboven betekent dat hij overbelast is.`}}},swap:{term:{t:0,b:{t:2,i:[{t:3}],s:`Swap`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Schijfruimte die wordt gebruikt als overloop wanneer het RAM vol raakt. Zwaar swap-gebruik vertraagt de host - een teken dat hij geheugen tekortkomt.`}}},throttle:{term:{t:0,b:{t:2,i:[{t:3}],s:`Throttling`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Wanneer het board zijn snelheid verlaagt om zichzelf te beschermen - meestal door een te zwakke voeding (onderspanning) of oververhitting. Wordt vooral gemeld op Raspberry Pi.`}}},ntp:{term:{t:0,b:{t:2,i:[{t:3}],s:`NTP / kloksynchronisatie`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Het Network Time Protocol houdt de klok van de host nauwkeurig. Een niet-gesynchroniseerde klok kan timelapses, logboeken en TLS-certificaten verstoren.`}}},locale:{term:{t:0,b:{t:2,i:[{t:3}],s:`Locale`}},def:{t:0,b:{t:2,i:[{t:3}],s:`De taal- en toetsenbordindelingsinstellingen van de host, gebruikt door het OS voor tekst, datums en de console-keymap.`}}},service:{term:{t:0,b:{t:2,i:[{t:3}],s:`Dienst (unit)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Een achtergrondprogramma beheerd door systemd - Klipper, Moonraker, de webcamstreamer en de netwerkstack draaien allemaal als diensten.`}}},enabled:{term:{t:0,b:{t:2,i:[{t:3}],s:`Ingeschakeld / uitgeschakeld`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Of een dienst automatisch start bij het opstarten. 'enabled' start bij het opstarten; 'disabled' niet; 'static' wordt alleen door een andere dienst gestart.`}}},mask:{term:{t:0,b:{t:2,i:[{t:3}],s:`Maskeren`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Een sterkere vorm van uitschakelen - de dienst kan helemaal niet worden gestart (ook niet door een andere dienst) totdat hij wordt gedemaskeerd. Gebruik met zorg.`}}}}},monitor:{refresh:{t:0,b:{t:2,i:[{t:3}],s:`Verversen`}},autoRefresh:{t:0,b:{t:2,i:[{t:3}],s:`Automatisch verversen`}},loading:{t:0,b:{t:2,i:[{t:3}],s:`Hoststatus lezen…`}},host:{t:0,b:{t:2,i:[{t:3}],s:`Host`}},hostname:{t:0,b:{t:2,i:[{t:3}],s:`Hostnaam`}},distro:{t:0,b:{t:2,i:[{t:3}],s:`OS`}},kernel:{t:0,b:{t:2,i:[{t:3}],s:`Kernel`}},uptime:{t:0,b:{t:2,i:[{t:3}],s:`Uptime`}},cpu:{t:0,b:{t:2,i:[{t:3}],s:`CPU`}},temp:{t:0,b:{t:2,i:[{t:3}],s:`Temperatuur`}},load:{t:0,b:{t:2,i:[{t:3}],s:`Belasting (1·5·15m)`}},cores:{t:0,b:{t:2,i:[{t:3}],s:`Cores`}},throttled:{t:0,b:{t:2,i:[{t:3}],s:`Gethrottled`}},memory:{t:0,b:{t:2,i:[{t:3}],s:`Geheugen`}},ram:{t:0,b:{t:2,i:[{t:3}],s:`RAM`}},swap:{t:0,b:{t:2,i:[{t:3}],s:`Swap`}},disk:{t:0,b:{t:2,i:[{t:3}],s:`Schijf`}},network:{t:0,b:{t:2,i:[{t:3}],s:`Netwerk`}},iface:{t:0,b:{t:2,i:[{t:3}],s:`Interface`}},ip:{t:0,b:{t:2,i:[{t:3}],s:`IP-adres`}},ssid:{t:0,b:{t:2,i:[{t:3}],s:`Wi-Fi`}},signal:{t:0,b:{t:2,i:[{t:3}],s:`Signaal`}},timeLocale:{t:0,b:{t:2,i:[{t:3}],s:`Tijd & Locale`}},timezone:{t:0,b:{t:2,i:[{t:3}],s:`Tijdzone`}},ntp:{t:0,b:{t:2,i:[{t:3}],s:`Kloksynchronisatie`}},synced:{t:0,b:{t:2,i:[{t:3}],s:`Gesynchroniseerd`}},syncing:{t:0,b:{t:2,i:[{t:3}],s:`Synchroniseren…`}},ntpOff:{t:0,b:{t:2,i:[{t:3}],s:`Uit`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Taal`}},keymap:{t:0,b:{t:2,i:[{t:3}],s:`Keymap`}},topProcesses:{t:0,b:{t:2,i:[{t:3}],s:`Topprocessen`}},command:{t:0,b:{t:2,i:[{t:3}],s:`Opdracht`}},cpuPct:{t:0,b:{t:2,i:[{t:3}],s:`CPU%`}},memPct:{t:0,b:{t:2,i:[{t:3}],s:`GEH%`}},pid:{t:0,b:{t:2,i:[{t:3}],s:`PID`}}},services:{warning:{t:0,b:{t:2,i:[{t:3}],s:`De verkeerde dienst stoppen of uitschakelen kan de printer offline halen. Kritieke diensten zijn gemarkeerd; beschermde diensten kunnen niet worden gestopt.`}},search:{t:0,b:{t:2,i:[{t:3}],s:`Diensten zoeken…`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Verversen`}},loading:{t:0,b:{t:2,i:[{t:3}],s:`Diensten opsommen…`}},loadingDetail:{t:0,b:{t:2,i:[{t:3}],s:`Dienst lezen…`}},loadingLogs:{t:0,b:{t:2,i:[{t:3}],s:`Logboek lezen…`}},summary:{t:0,b:{t:2,i:[{t:4,k:`total`},{t:3,v:` diensten · `},{t:4,k:`active`},{t:3,v:` actief · `},{t:4,k:`failed`},{t:3,v:` mislukt`}]}},filter:{all:{t:0,b:{t:2,i:[{t:3}],s:`Alle`}},active:{t:0,b:{t:2,i:[{t:3}],s:`Actief`}},inactive:{t:0,b:{t:2,i:[{t:3}],s:`Inactief`}},failed:{t:0,b:{t:2,i:[{t:3}],s:`Mislukt`}},enabled:{t:0,b:{t:2,i:[{t:3}],s:`Ingeschakeld`}}},stateActive:{t:0,b:{t:2,i:[{t:3}],s:`Actief`}},stateInactive:{t:0,b:{t:2,i:[{t:3}],s:`Inactief`}},stateFailed:{t:0,b:{t:2,i:[{t:3}],s:`Mislukt`}},critical:{t:0,b:{t:2,i:[{t:3}],s:`Kritiek`}},protected:{t:0,b:{t:2,i:[{t:3}],s:`Beschermd`}},state:{t:0,b:{t:2,i:[{t:3}],s:`Status`}},startup:{t:0,b:{t:2,i:[{t:3}],s:`Opstart`}},unitFile:{t:0,b:{t:2,i:[{t:3}],s:`Unit-bestand`}},action:{start:{t:0,b:{t:2,i:[{t:3}],s:`Starten`}},stop:{t:0,b:{t:2,i:[{t:3}],s:`Stoppen`}},restart:{t:0,b:{t:2,i:[{t:3}],s:`Herstarten`}},enable:{t:0,b:{t:2,i:[{t:3}],s:`Inschakelen`}},disable:{t:0,b:{t:2,i:[{t:3}],s:`Uitschakelen`}},mask:{t:0,b:{t:2,i:[{t:3}],s:`Maskeren`}},unmask:{t:0,b:{t:2,i:[{t:3}],s:`Demaskeren`}}},actionOk:{t:0,b:{t:2,i:[{t:4,k:`action`},{t:3,v:` voltooid.`}]}},actionFailed:{t:0,b:{t:2,i:[{t:4,k:`action`},{t:3,v:` mislukt.`}]}},deleteFailed:{t:0,b:{t:2,i:[{t:3}],s:`Kon het unit-bestand niet verwijderen.`}},confirmAction:{t:0,b:{t:2,i:[{t:4,k:`action`},{t:3,v:` "`},{t:4,k:`name`},{t:3,v:`"?`}]}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:`Ja, doe maar`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annuleren`}},deleteUnit:{t:0,b:{t:2,i:[{t:3}],s:`Unit-bestand verwijderen…`}},deletePrompt:{t:0,b:{t:2,i:[{t:3,v:`Dit verwijdert het unit-bestand permanent. Typ "`},{t:4,k:`name`},{t:3,v:`" om te bevestigen.`}]}},deleteConfirm:{t:0,b:{t:2,i:[{t:3}],s:`Permanent verwijderen`}},deleted:{t:0,b:{t:2,i:[{t:3}],s:`Unit-bestand verwijderd.`}},logs:{t:0,b:{t:2,i:[{t:3}],s:`Recent logboek`}},noLogs:{t:0,b:{t:2,i:[{t:3}],s:`Geen loguitvoer.`}}},cleanup:{subtitle:{t:0,b:{t:2,i:[{t:3}],s:`Vink aan wat je wilt verwijderen en schoon op. Alleen caches en oude logboeken - prints en configs blijven veilig.`}},rescan:{t:0,b:{t:2,i:[{t:3}],s:`Opnieuw scannen`}},scanning:{t:0,b:{t:2,i:[{t:3}],s:`Schijf scannen…`}},na:{t:0,b:{t:2,i:[{t:3}],s:`n.v.t.`}},items:{t:0,b:{t:2,i:[{t:4,k:`n`},{t:3,v:` bestanden`}]}},freed:{t:0,b:{t:2,i:[{t:4,k:`size`},{t:3,v:` vrijgemaakt.`}]}},selectedTotal:{t:0,b:{t:2,i:[{t:3,v:`Geselecteerd: `},{t:4,k:`size`}]}},clean:{t:0,b:{t:2,i:[{t:3}],s:`Geselecteerde opschonen`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`De geselecteerde items verwijderen?`}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:`Ja, opschonen`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annuleren`}},running:{t:0,b:{t:2,i:[{t:3}],s:`Opschonen…`}},someFailed:{t:0,b:{t:2,i:[{t:3}],s:`Sommige items konden niet worden opgeschoond.`}},targets:{apt:{label:{t:0,b:{t:2,i:[{t:3}],s:`Pakketcache`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Gedownloade .deb-installatiebestanden die apt niet meer nodig heeft.`}}},journal:{label:{t:0,b:{t:2,i:[{t:3}],s:`Systeemjournaal`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Oude systemd-logboeken - teruggebracht tot de meest recente 50 MB.`}}},cache:{label:{t:0,b:{t:2,i:[{t:3}],s:`Gebruikerscache`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Opnieuw te genereren bestanden in ~/.cache (thumbnails, pip, enz.).`}}},tmp:{label:{t:0,b:{t:2,i:[{t:3}],s:`Tijdelijke bestanden`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Je eigen bestanden in /tmp ouder dan een dag.`}}},logs:{label:{t:0,b:{t:2,i:[{t:3}],s:`Geroteerde logboeken`}},desc:{t:0,b:{t:2,i:[{t:3}],s:`Oude, geroteerde Klipper/Moonraker-logboeken (het live logboek blijft behouden).`}}}}},system:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Systeeminstellingen lezen…`}},done:{t:0,b:{t:2,i:[{t:3}],s:`Klaar.`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`Toepassen`}},timeTitle:{t:0,b:{t:2,i:[{t:3}],s:`Tijd & Datum`}},timezone:{t:0,b:{t:2,i:[{t:3}],s:`Tijdzone`}},ntp:{t:0,b:{t:2,i:[{t:3}],s:`Tijd automatisch instellen (NTP)`}},manualTime:{t:0,b:{t:2,i:[{t:3}],s:`De klok handmatig instellen`}},manualTimeHint:{t:0,b:{t:2,i:[{t:3}],s:`Zet automatische tijd uit om de klok met de hand in te stellen.`}},localeTitle:{t:0,b:{t:2,i:[{t:3}],s:`Taal & Toetsenbord`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Taal`}},keymap:{t:0,b:{t:2,i:[{t:3}],s:`Console-keymap`}},hostnameTitle:{t:0,b:{t:2,i:[{t:3}],s:`Hostnaam`}},hostnameHint:{t:0,b:{t:2,i:[{t:3}],s:`Alleen letters, cijfers en koppeltekens. Volledig effect na een herstart.`}},powerTitle:{t:0,b:{t:2,i:[{t:3}],s:`Voeding`}},powerWarning:{t:0,b:{t:2,i:[{t:3}],s:`Herstarten en uitschakelen worden geweigerd terwijl er een print loopt.`}},reboot:{t:0,b:{t:2,i:[{t:3}],s:`Herstarten`}},shutdown:{t:0,b:{t:2,i:[{t:3}],s:`Uitschakelen`}},confirmReboot:{t:0,b:{t:2,i:[{t:3}],s:`De host nu herstarten?`}},confirmShutdown:{t:0,b:{t:2,i:[{t:3}],s:`De host nu uitschakelen?`}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:`Ja`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Annuleren`}},needsSetup:{t:0,b:{t:2,i:[{t:3}],s:`Deze actie vereist wachtwoordloze sudo. Voer op de printer uit: sudo bash scripts/install.sh sudoers - probeer het dan opnieuw.`}},failed:{t:0,b:{t:2,i:[{t:3}],s:`Die wijziging is niet toegepast.`}},network:{title:{t:0,b:{t:2,i:[{t:3}],s:`Netwerk (IPv4)`}},unavailable:{t:0,b:{t:2,i:[{t:3}],s:`Netwerkbewerking is niet beschikbaar op deze host (NetworkManager niet geïnstalleerd).`}},device:{t:0,b:{t:2,i:[{t:3}],s:`Apparaat`}},method:{t:0,b:{t:2,i:[{t:3}],s:`IP-methode`}},auto:{t:0,b:{t:2,i:[{t:3}],s:`DHCP (automatisch)`}},manual:{t:0,b:{t:2,i:[{t:3}],s:`Statisch (handmatig)`}},address:{t:0,b:{t:2,i:[{t:3}],s:`IP-adres`}},cidr:{t:0,b:{t:2,i:[{t:3}],s:`Subnet (CIDR)`}},gateway:{t:0,b:{t:2,i:[{t:3}],s:`Gateway`}},dns:{t:0,b:{t:2,i:[{t:3}],s:`DNS-servers`}},dnsHint:{t:0,b:{t:2,i:[{t:3}],s:`Door komma's gescheiden, bijv. 1.1.1.1, 8.8.8.8 (optioneel)`}},warning:{t:0,b:{t:2,i:[{t:3}],s:`Het wijzigen van het IP kan dit paneel verbreken - je moet mogelijk opnieuw verbinden op het nieuwe adres.`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`Netwerkinstellingen toepassen`}},confirmPrompt:{t:0,b:{t:2,i:[{t:3,v:`Dit kan het paneel onbereikbaar maken. Typ de apparaatnaam "`},{t:4,k:`device`},{t:3,v:`" om te bevestigen.`}]}},confirmYes:{t:0,b:{t:2,i:[{t:3}],s:`Toepassen & overschakelen`}},applyingReconnect:{t:0,b:{t:2,i:[{t:3}],s:`Toepassen… als het paneel niet meer reageert, verbind opnieuw op het nieuwe IP van de printer.`}}}},boot:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Hoe de host opstart: het standaarddoel en de opstart-splash. Hier alleen-lezen; de splash wijzigen komt later.`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Vernieuwen`}},loading:{t:0,b:{t:2,i:[{t:3}],s:`Opstartconfiguratie lezen…`}},defaultTarget:{t:0,b:{t:2,i:[{t:3}],s:`Standaarddoel`}},graphical:{t:0,b:{t:2,i:[{t:3}],s:`Grafisch`}},console:{t:0,b:{t:2,i:[{t:3}],s:`Console`}},plymouth:{t:0,b:{t:2,i:[{t:3}],s:`Plymouth-thema`}},none:{t:0,b:{t:2,i:[{t:3}],s:`geen`}},splash:{t:0,b:{t:2,i:[{t:3}],s:`Opstart-splash`}},noSplash:{t:0,b:{t:2,i:[{t:3}],s:`Geen opstart-splash gevonden op deze host.`}},changeHint:{t:0,b:{t:2,i:[{t:3}],s:`De splash wijzigen + een ontwerpstudio komen in een latere update.`}}}}};export{e as default};